    /// The languages this build has text for, source first. `draft` languages carry the draft label.
    public static let languages: [Language] = [
        Language(tag: "en", name: "English", flag: "gb", draft: false),
        Language(tag: "de", name: "Deutsch", flag: "de", draft: true),
        Language(tag: "es-419", name: "Español (Latinoamérica)", flag: "mx", draft: true),
        Language(tag: "fr", name: "Français", flag: "fr", draft: true),
        Language(tag: "id", name: "Bahasa Indonesia", flag: "id", draft: true),
        Language(tag: "it", name: "Italiano", flag: "it", draft: true),
        Language(tag: "ja", name: "日本語", flag: "jp", draft: true),
        Language(tag: "pl", name: "Polski", flag: "pl", draft: true),
        Language(tag: "pt-BR", name: "Português (Brasil)", flag: "br", draft: true),
        Language(tag: "ru", name: "Русский", flag: "ru", draft: true),
        Language(tag: "sv", name: "Svenska", flag: "se", draft: true),
        Language(tag: "tr", name: "Türkçe", flag: "tr", draft: true),
        Language(tag: "vi", name: "Tiếng Việt", flag: "vn", draft: true),
    ]

    public struct Language: Sendable, Equatable {
        public let tag: String
        /// The language's name in itself.
        public let name: String
        /// The ISO code of the flag shown beside the name, if the language has one.
        public let flag: String?
        public let draft: Bool
    }

    /// The bundled flag image of an ISO code (`flag-gb.png`), drawn 4:3.
    public static func flagURL(_ code: String) -> URL? {
        bundle.url(forResource: "flag-\(code)", withExtension: "png")
    }

    private final class BundleToken {}

    private static var bundle: Bundle {
        #if SWIFT_PACKAGE
        Bundle.module
        #else
        Bundle(for: BundleToken.self)
        #endif
    }

    private static func string(_ key: String, fallback: String) -> String {
        bundle.localizedString(forKey: key, value: fallback, table: "Localizable")
    }

    private static func format(_ key: String, fallback: String, _ arguments: CVarArg...) -> String {
        String(format: string(key, fallback: fallback), locale: Locale.current, arguments: arguments)
    }
}
